(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pirate"] = {"ui":{"skip":"Skip to the cargo","back":"← Back to AI-gile, matey","lang.button":"Tongue: {name}","lang.dialog":"Pick yer tongue","lang.search":"Search the tongues","lang.none":"No tongue matches, arr","lang.notYet":"{name} be not translated yet","theme.aria":"Swap sails: light, dark or black","theme.toLight":"Hoist the light sails","theme.toDark":"Hoist the dark sails","theme.toBlack":"Hoist the black sails (true black, easy on OLED screens)","words.underline":"Underline these here words on the page","words.underlineHelp":"Hover o'er or tap a dotted word to see what it be meanin'.","index.title":"AI-gile: yer AI dev crew, aboard one board","index.description":"AI-gile be a kanban board for AI coding crews. They toil while ye snore; ye get one short pile o' things to decide, test and accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Yer AI dev crew, aboard one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and unfinished: thanks fer tryin' it, matey!","hero.lede":"They build while ye sleep. Ye wake to one short pile: a few questions, a few things to test, a purple diamond or two. Click, accept, back to yer grog.","dl.windows":"Windows app","dl.browser":"Sail it in yer browser","dl.messenger":"📱 Messenger fer yer phone","dl.soon":"Comin' soon","dl.notify":"🔔 Ring the bell when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the crew never needs a stand-up grog. (They hold stand-ups anyway, arr.)","pitch.h2":"AI-gile in as many words as ye like","pitch.lede":"Pick a length, from one word to 144. Each length be its own tale, written fer that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another yarn","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card aboard the board right now","count.line.html.other":"{n} cards aboard the board right now","people.humans.html.one":"👥 {n} human hearty","people.humans.html.other":"👥 {n} human hearties","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} hard at work right now, arr","people.working.html.other":"⚡ {n} hard at work right now, arr","pre.title":"AI-gile: somethin's bein' built","pre.description":"Somethin's bein' built here: a board where AI crews build what ye ask fer, an' teach ye as they go. Closed pre-alpha with me hearties fer now.","pre.h1":"Somethin's bein' built here. 🤫","pre.line":"A board where AI crews build what ye ask fer, an' teach ye as they go. Closed pre-alpha with me hearties fer now.","pre.btn":"🔔 Ring the bell when it opens","pre.peek":"Behind the glass: the real board, live. Every card be a coloured bar.","pre.peekFake":"Behind the glass: what a board hard at work looks like.","features.aria":"What it does","f.pile.h":"One pile fer ye","f.pile.html":"<b>For ye</b> holds everythin' waitin' on ye, across every project: questions, things to test, tasks only a human can do. Yer queue says what be next and how long it takes.","f.sleep.h":"Crews that work while ye sleep","f.sleep.p":"Each project has a captain and a crew o' AI agents. Comment on a card and the crew wakes, does the work, and hands it back with steps a weary landlubber can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Afore anythin' reaches ye, a tester follows the steps in a copy o' the app and shows what it saw, with a screenshot. Flick through the passed ones and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over shows what changed: the files, the diff, the screenshots. No openin' every app to see if it be done.","f.chat.h":"Parley with yer captains","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds fer what needs ye. Message a captain an idea; they turn it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keeps its own deck tidy","f.tidy.p":"Related cards fold into one, muddled titles get fixed, and a token check keeps the code lean. Fewer things to switch between, less to ponder.","f.private.h":"Yers, on yer own computer","f.private.li1":"The board sails on yer own machine and only answers to ye.","f.private.li2":"Private DMs 'twixt people be end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In yer own tongue","f.lang.p":"Over 120 tongues, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick swap back to English fer the industry jargon.","f.service.h":"From an idea to a real service, arr","f.service.p":"Built somethin' with AI that folk now use? Mark it as a service and the board helps ye run a tight ship: uptime checks, a public status page, storms with a write-up, changes that need a Go, backups checked daily. Help teaches each step as ye sail.","msgr.h2":"AI-gile Messenger: yer crew in yer pocket","msgr.p1":"Parley with yer AI crew without openin' the board. Chat with yer project captains an' yer mateys, an' see a card's test steps an' answer 'em, all from yer phone.","msgr.p2":"To pair it, scan a QR code on yer board. First time aboard? A friendly demo chat shows ye the ropes.","msgr.when":"Android first, then a web version fer phones an' iPhone.","msgr.who":"Yer project captain","msgr.b1":"The dark mode fix be ready. Want the test steps?","msgr.b2":"Aye, please!","msgr.b3":"1. Open Settings. 2. Pick Dark. Does it look shipshape?","tl.aria":"Timeline from the first parley to the roadmap","tl.h2":"From the first chat to what be next","tl.lede":"Real dates and times, in yer own time zone. After today it be the plan, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Join the crew","join.lede":"AI-gile be built by a bearded weirdo with AuDHD and a few mental health battles, and a great many patient agents. It be private fer now, in a closed alpha with friends. Want a go when it opens up?","join.btn":"Register interest","join.small":"We'll send ye a letter, nothin' else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up grog.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"What we stow","footer.thanks":"Calls thanks to ChilledChat","form.sending":"Sendin'…","form.failed":"That didn't work: try again later, arr.","form.offline":"Couldn't reach AI-gile: try again later.","form.keep":"We only use this to send ye a reply, then we scuttle it. No trackers, no cookies.","form.keepLink":"What we stow","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave yer email to hear when AI-gile's closed alpha or beta opens.","interest.h1":"🔔 Ring the bell when it opens","interest.lede":"AI-gile be in closed pre-alpha. Leave yer email and we'll write once, when there be a berth fer ye.","interest.email":"Yer email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, lots o' changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Put me on the list","interest.thanks":"Thanks! Ye be on the list.","licence.title":"AI-gile: business licence","licence.description":"Usin' AI-gile in yer business? Apply fer a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usin' AI-gile at work? Tell us who ye be and what ye do. If it does some good, the licence be free.","licence.company":"Company","licence.website":"Website","licence.what":"What ye do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Calm seas","status.intro":"Be AI-gile shipshape right now? This page checks the website, board sharin', calls and the download every 5 minutes.","status.up":"Shipshape (answered in {ms} ms)","status.slow":"Didn't answer the last check, tryin' again","status.down":"Sunk: didn't answer the last two checks","status.svc.web":"Website","status.svc.web.offers":"This site: what AI-gile be, and the interest form","status.svc.boards":"Board sharin'","status.svc.boards.offers":"Public boards, messages 'twixt mateys and invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video and screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer and invite links","status.checking":"Checkin'…","status.offline":"Can't reach the status service right now (retryin')","status.updated":"updated {ago}","status.justNow":"just now, matey","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","privacy.title":"AI-gile: what we stow","privacy.h1":"What we stow","privacy.lede":"Short version: only what ye send us, and not fer long.","privacy.only":"Only what ye send us: what ye type into a form, like yer email. Nothin' else about ye.","privacy.sealed":"It be sealed tight so our server can't read it: in yer browser afore it leaves port (on an older browser, the moment it makes land). Only our own board can crack it open.","privacy.server":"It be scuttled from the server as soon as it reaches our board. Anythin' still there after 30 days gets scuttled anyway.","privacy.board":"We keep it on our board only till we've replied to ye, then scuttle it there too.","privacy.none":"No trackers, no cookies, no analytics, arr.","privacy.local":"Yer tongue and yer light or dark sails stay in yer own browser. They never be sent to us.","privacy.ask":"Want it gone sooner? Reply to our email and say so, matey.","live.h2":"Watch her bein' built, live, matey","live.caption":"Every card be hidden: ye see the shape o' the work, not the words.","live.watching.one":"live: {n} watchin'","live.watching.other":"live: {n} watchin'","live.last.now":"Last card moved just now","live.last.min.one":"Last card moved {n} min ago","live.last.min.other":"Last card moved {n} min ago","live.last.hour.one":"Last card moved {n} hour ago","live.last.hour.other":"Last card moved {n} hours ago","live.last.day.one":"Last card moved {n} day ago","live.last.day.other":"Last card moved {n} days ago","live.offline":"The live board be catchin' its breath. Sail back soon, matey.","live.cols":"Backlog Hold|Yet to do|Aboard and workin'|Crew be checkin'|For ye to test|For the crew|Done and dusted"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban!","Robots.","Delegated."]},{"n":2,"texts":["Robot kanban.","Crews, organised.","Ideas, built."]},{"n":3,"texts":["Kanban fer robots.","Ideas become features.","Free crew kanban."]},{"n":5,"texts":["Kanban board sailed by agents.","Ye write cards. Crew builds.","Free, local, tested, slightly daft."]},{"n":8,"texts":["A free kanban board where AI agents do yer toilin'.","Scribble an idea. Crew builds it. Ye accept.","Agile fer one human and many patient robots."]},{"n":13,"texts":["A kanban board on yer own computer where AI agents grab the cards, arr.","Write an idea. A crew o' agents builds it. A tester checks it.","Free, no accounts, no trackers: a board, some robots, and ye be captain."]},{"n":21,"texts":["AI-gile be a kanban board fer workin' with AI coding agents. They grab the cards; ye test and accept 'em, matey.","Each project gets a captain and a crew o' AI agents. Comment on any card and the crew sets to work.","A free, personal to-do board that sails on yer own computer. The deckhands be robots. The one sayin' aye be ye."]},{"n":34,"texts":["Ye pin ideas on a board. A crew o' AI agents turns 'em into workin' features, tests 'em, and hands 'em back with steps to try. Nothin' counts as done 'til ye say so, arr.","AI-gile be a homemade kanban board that Rich built with a great deal o' help from the agents it now commands. It be free, sails on yer computer, and be shared with friends, not sold.","Picture a plain kanban board, with columns from Backlog to Done, except the cards be grabbed by AI agents. They report progress, ask questions when stuck, and always wait fer yer thumbs up."]},{"n":55,"texts":["AI-gile be a kanban board where the crew be made o' AI agents. Each project has a captain who plans the work and hands who build it. When a feature be ready, an AI tester tries it and takes a screenshot, then it lands in yer pile. Accept it, or comment and they rework it, arr.","It started as one scallywag's way o' keepin' track o' many AI coding sessions at once, and grew into a proper board. It sails on yer machine, needs no account, and has no trackers. It be free fer friends and the curious. It be unfinished too, so expect rough planks and the odd surprise.","Here be the honest version. Ye still must have the ideas, and ye still must check the results. What AI-gile does be everythin' in between: it keeps the cards in order, wakes the right agent when ye comment, shows exactly what changed, and gathers it all into one short pile fer ye."]},{"n":89,"texts":["AI-gile be a free kanban board that ye sail on yer own computer. Instead o' people, each project has a crew o' AI agents: a captain who turns yer ideas into cards and a plan, and hands who grab the cards in priority order. When somethin' be built, an AI tester follows the test steps and shows ye what it saw. Then it waits in one pile marked For ye. Ye accept it, or ye comment and the crew has another go. Nothin' ever reaches Done without ye.","Some features ye might not expect. A night watch keeps the To do column stocked while ye sleep, choosin' cards that need no answer from ye. A token counter shows how much the agents have used today and this week, and No Token Mode orders 'em to stop spendin'. Ye can message friends, and private messages be end-to-end encrypted. The board speaks about 120 tongues, includin' Dutch, Flemish, pirate and Klingon. None o' it costs a doubloon, and nobody be tryin' to sell it to ye either.","AI-gile be a small, personal project, not a company. Rich wanted to mind several AI coding projects without openin' every app to check on 'em, so he and the agents built a board fer it, then used the board to build the rest o' itself. It be in closed pre-alpha, which means it works, mostly, fer a handful o' friends. There be no pricin' page, no newsletter and no growth plan. If it sounds useful, ye can ask to try it when it opens up a little more."]},{"n":144,"texts":["AI-gile be a kanban board fer one human and a great many AI agents. It sails on yer own computer and it be completely free. Ye add projects, and each project gets a captain and a small crew. Ye chat with the captain, a bit like Discord, and describe an idea; the captain turns it into cards and a plan, then waits fer ye to press Go. The crew works through the cards in priority order, usin' a simple command line made fer language models. Afore anythin' comes back to ye, an AI tester follows the steps in a copy o' the app and attaches a screenshot. Finished work lands in yer pile with the changed files and the diff. Ye accept it, or ye leave a comment and the crew wakes up and tries again. Only ye can move a card to Done, matey.","A day with AI-gile, roughly. In the evenin' ye leave a few comments: this button be in the wrong place, that list should be sorted, could we have a dark mode. Ye go to yer hammock. The agents read the comments, make the changes, test 'em and hand 'em back to ye. If To do runs dry, the night watch fills it from the backlog with cards that need no answer from ye. In the mornin' there be one short pile: a couple o' questions and a few things to try, each with steps a sleepy sailor can follow and a screenshot o' it workin'. Ye click through, accept the good ones and send back the rest. A token counter shows what it all used, and No Token Mode be there fer lean weeks. Then ye have breakfast, which the agents cannot help with yet.","First, what AI-gile be not. It be not a startup, it be not fer sale, and nobody be collectin' yer data. It be a free board that sails on yer computer, with no accounts, no trackers and no cookies. What it be: one tidy place to see every AI coding project at once, with a crew o' agents doin' the cards and ye makin' the decisions. It folds related cards together, fixes muddled titles, and keeps an eye on how lean the code stays. It speaks about 120 tongues, from Dutch and Flemish to pirate and Klingon. Friends can message each other, privately and encrypted. It was built by Rich and a great many patient agents, mostly usin' itself. It be in closed pre-alpha, so it be rough in places. If it sounds like fun, ask nicely and ye might get aboard early, arr."]}],"quips":{"1":"One word. Bold. Possibly too bold, arr.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths be story points, by the way. Of course they be.","55":"Fifty-five words. Two cards got finished while ye read that.","144":"That be the long one. There be no 233. The crew has gone to bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first parley, afore any code existed.","first-board.name":"First board","first-board.line":"A board that tracks its own buildin': cards, columns, drag and drop, projects.","team-roles.name":"Crew and roles","team-roles.line":"Agent profiles, crew templates, spaces and who does what.","install.name":"Install and releases","install.line":"A zip a friend can install, self-updates, channels and rollin' back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, save yer limit.","friends.name":"Friends and sharin'","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Tongues","languages.line":"Every screen text in a tongue file, with Dutch and Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks every hand-over first and shows what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streamin'","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board fer folk who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the crews on task while ye sleep.","p-more.name":"Everythin' else","p-more.line":"Smaller ideas still waitin' their turn.","p-android.name":"Phone and Android","p-android.line":"Reach yer board from a phone, then a native Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More tongues","p-languages.line":"More than a hundred tongues, and an immersion mode fer learners.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex or Gemini per agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Lookin' after ye","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and plannin' fer growth.","p-livestream.name":"Streamin' extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."},"words":{"button":"📖 Industry jargon","h":"📖 Words explained, matey","intro":"The words ye meet in AI-gile, in plain talk: buildin' it, changin' it safely, keepin' it runnin' fer the folk who use it, and sailin' as a crew with AI.","search":"Search a word…","none":"No word matches that.","close":"Batten down","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Buildin' it"},{"id":"change","name":"🔀 Changin' it safely"},{"id":"run","name":"🛎️ Runnin' a service"},{"id":"team","name":"🤝 Sailin' as a crew (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"The project’s folder of code and its full history of commits, usually also kept on GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line of work in the code, so changes can be made without touchin' the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot of the code, with a short note of what changed. Ye can always go back to one.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sendin' saved snapshots (commits) from this computer up to GitHub, so they be backed up and shared."},{"id":"merge","g":"build","word":"Merge","text":"Joinin' a branch’s changes back into the main version."},{"id":"pr","g":"build","word":"Pull request","text":"Askin' for a branch’s changes to be checked and merged into the main version.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tidyin' the code without changin' what it does: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"Somethin' that doesn’t work the way it should.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Tryin' a finished piece of work to check it does what was asked, before ye accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short fer quality assurance: the automatic checks that run afore anythin' goes live. When QA be red, somethin' failed, and it can’t go live till that be fixed.","also":["quality checks","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"Puttin' a new version live, for example onto a server where folk use it."},{"id":"release","g":"change","word":"Release","text":"A named haul o' finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Sailin' back to the last version that worked when a new one brings trouble. In AI-gile it makes a checklist o' the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that folk use, as opposed to a copy fer tryin' things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to somethin' folk rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Somethin' that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps 'em in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a calm Tuesday evenin'. Outside a window a change card can’t be finished, unless it be an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just afore a change goes live: each hand who has to approve says Go or No go. It only sails when they all agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waitin' fer an aye afore work starts. A card a friend raises, or a change, waits in ✅ Approvals till ye approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch o' time, like a stream, a demo or the night, when nothin' goes live. The crews keep workin' and testin', but goin' live waits till it ends. Elsewhere it be called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Somethin' ye built that folk rely on, like a website or an app, looked after so it keeps workin'. Tick “This project be a service” and say what it offers, who uses it and who be on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that yer service still answers. If it fails several times in a row, AI-gile opens a storm card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service be workin' (green, orange or red) with the latest word, so the folk who use it can check instead o' askin'.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Somethin' that be broken fer the folk usin' it right now, like the website bein' sunk; aboard this ship we call it a storm. A 🔥 storm aboard card jumps the queue: gettin' it afloat again comes first.","also":["incidents","storm aboard","storms aboard"]},{"id":"major","g":"run","word":"Major incident","text":"A great storm: many folk hit, or doubloons or data at risk. One button puts every crew on it (all hands), wakes whoever be on call and asks fer a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Bein' the one who answers when somethin' breaks, even at night. Each service has an on-call crew member who be woken first fer its storms.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait fer a first answer, fer example an hour fer a storm aboard. After that it gets a red clock, so nothin' be quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after a storm, the after-storm reckonin': what happened, what helped and what to change, without blamin' anyone. A storm card can’t be closed without one.","also":["post-mortems","postmortem","post-incident review","after-storm reckoning"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more storms. A 🧩 problem card groups storms that keep comin' back, so the cause be found and fixed fer good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason somethin' broke, not just what ye saw goin' wrong. Fix the root cause and the storm stops comin' back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep the ship sailin' till the real fix be ready, like restartin' somethin' when it gets stuck. It be written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause be understood and that has a workaround, but ain’t fixed yet. 🧩 Known errors lists 'em, so every hand uses the workaround instead o' diggin' again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step orders fer fixin' a known kind o' trouble, so it be done the same way, quick, every time. After a great storm the crew can propose one fer ye to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy o' yer data from earlier, to fall back on if somethin' be lost or damaged. AI-gile makes a backup o' yer boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Puttin' data back from a backup. A backup only really counts once ye know it can be restored, so it be worth tryin' now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideas and work not planned in yet. Nothin' there gets worked on until it moves to Yet to do."},{"id":"sprint","g":"team","word":"Sprint","text":"A short stretch of work (often a week or two) with an agreed set of cards to finish.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"A quick check-in: what each crew member did, what they do next, and what be stoppin' 'em.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"A board with columns (To do, In progress, Done) where cards move left to right as work happens."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: the most cards a column should hold, so the crew finishes things before startin' more.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition o' Done","text":"The crew’s short checklist o' what “finished” means, like tested and explained, afore a card be handed to ye. Its twin, the Definition o' Ready, says when a card be clear enough to start.","also":["Definition of Done","Definition of Ready","Definition o' Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waitin' fer ye to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the crew works, to agree on one thing to do better. In AI-gile a retro suggests a change to the crew’s ways o' workin', and ye say Set sail or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair o' eyes: another AI checks each card’s work afore it reaches ye, so fewer mistakes slip aboard.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every crew drops other work to help on one urgent project till it be sorted. Other projects wait meanwhile.","also":["swarming","all hands"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowin': spots stuck cards, nudges the crews and reminds ye o' what be waitin'. In AI-gile the Scrum captain does this across every project.","also":["Scrum captain","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"An AI that works on its own on a task: reads the code, makes changes, runs checks, and reports back to the captain.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"The unit AI usage be counted in: roughly a few letters of text read or written. Fewer tokens, more of yer plan left.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"A small command that runs by itself at a set moment, e.g. when an AI session starts, so the crew hears yer comments.","also":["hooks"]}]}};
